package org.novasos.healthysv2.patient;
import java.time.*; import java.util.UUID; import jakarta.persistence.*;
@Entity @Table(name="patient_identifier",schema="patient") class PatientIdentifier {@Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="patient_id") private Patient patient;@Column(nullable=false,length=50) private String type;@Column(nullable=false,length=150) private String value;private String issuer;@Column(name="country_id") private UUID countryId;@Column(name="expiration_date") private LocalDate expirationDate;protected PatientIdentifier(){}static PatientIdentifier create(Patient p,String t,String v,String i,UUID c,LocalDate e){var x=new PatientIdentifier();x.patient=p;x.update(t,v,i,c,e);return x;}void update(String t,String v,String i,UUID c,LocalDate e){type=Patient.required(t).toUpperCase();value=Patient.required(v);issuer=Patient.optional(i,false);countryId=c;expirationDate=e;}UUID getId(){return id;}String getType(){return type;}String getValue(){return value;}String getIssuer(){return issuer;}UUID getCountryId(){return countryId;}LocalDate getExpirationDate(){return expirationDate;}}
@Entity @Table(name="patient_insurance",schema="patient") class PatientInsurance {@Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="patient_id") private Patient patient;@Column(name="insurance_company_id",nullable=false) private UUID insuranceCompanyId;@Column(name="policy_number",length=100) private String policyNumber;@Column(name="member_number",length=100) private String memberNumber;@Column(name="start_date") private LocalDate startDate;@Column(name="end_date") private LocalDate endDate;@Column(name="is_primary",nullable=false) private boolean primary;protected PatientInsurance(){}static PatientInsurance create(Patient p,UUID c,String policy,String member,LocalDate start,LocalDate end,boolean primary){var x=new PatientInsurance();x.patient=p;x.update(c,policy,member,start,end,primary);return x;}void update(UUID c,String policy,String member,LocalDate start,LocalDate end,boolean primary){if(start!=null&&end!=null&&end.isBefore(start))throw new IllegalArgumentException("Invalid insurance dates");insuranceCompanyId=java.util.Objects.requireNonNull(c);policyNumber=Patient.optional(policy,false);memberNumber=Patient.optional(member,false);startDate=start;endDate=end;this.primary=primary;}void makeSecondary(){primary=false;}UUID getId(){return id;}UUID getInsuranceCompanyId(){return insuranceCompanyId;}String getPolicyNumber(){return policyNumber;}String getMemberNumber(){return memberNumber;}LocalDate getStartDate(){return startDate;}LocalDate getEndDate(){return endDate;}boolean isPrimary(){return primary;}}
@Entity @Table(name="patient_registration",schema="patient") class PatientRegistration {@Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="patient_id") private Patient patient;@Column(name="organization_id",nullable=false) private UUID organizationId;@Column(name="registration_number",nullable=false,length=100) private String registrationNumber;@Column(name="registered_at",nullable=false) private Instant registeredAt;@Column(nullable=false,length=30) private String status;protected PatientRegistration(){}static PatientRegistration create(Patient p,UUID o,String n,Instant at,String status){var x=new PatientRegistration();x.patient=p;x.update(o,n,at,status);return x;}void update(UUID o,String n,Instant at,String status){organizationId=java.util.Objects.requireNonNull(o);registrationNumber=Patient.required(n);registeredAt=at==null?Instant.now():at;this.status=Patient.normalize(status,"ACTIVE");}UUID getId(){return id;}UUID getOrganizationId(){return organizationId;}String getRegistrationNumber(){return registrationNumber;}Instant getRegisteredAt(){return registeredAt;}String getStatus(){return status;}}
